const out = []; // Basket for finished emails

/**
 * Every email the categorizer returned
 * Go through them one by one
 * "item" = current email
 */
for (const item of $input.all()) {

  /**
   * Did the categorizer decide on a category?
   * No labelId = confidence below the floor, or "other"
   * Tag nothing at all, so "-label:sorted" picks it up again
   * tomorrow night. It ages out by itself after 7 days.
   */
  if (!item.json.labelId) continue;

  /**
   * Put email in basket
   * "...item.json" -> spread operator
   * new field added = labelsToAdd
   * Label_11 = "sorted", now only applied when a category was decided
   */
  out.push({json: {...item.json, labelsToAdd: ['Label_11', item.json.labelId]} });

}

return out; // Get basket to pass to next node

const map = $('build_sender_map').first().json.senderMap ?? {};

return $input.all().map(item => {
  const j = item.json;

  const body = (j.text ?? '')
    .replace(/https?:\/\/\S+/g, '')   // tracking links, no signal, lots of tokens
    .replace(/\s+/g, ' ')             // collapse the newline soup
    .trim()
    .slice(0, 700);                   // enough to reach the actual point

  const From = j.from?.text ?? '';

  /**
   * Standard bulk-mail markers. Every platform and newsletter sets one
   * A human writing to you never does. Replaces any hardcoded domain list.
   */
  const h = j.headers ?? {};
  const isBulk = !!(h['list-unsubscribe'] || h['list-id']);

  // Same address extraction as build_sender_map, so the keys match
  const addr = From.match(/[\w.+-]+@[\w.-]+/)?.[0]?.toLowerCase();
  const hit = addr ? map[addr] : null;

  const senderHint = hit
    ? `Past mail from this sender: ${hit.n} of ${hit.total} were ${hit.top}.`
    : '';

  return{
    json: {
      id: j.id,
      threadId: j.threadId,
      labelIds: j.labelIds,
      internalDate: j.date,
      Subject: j.subject,
      From,
      body,
      senderHint,
      isBulk
    }
  };
});

const counts = {};   // sender -> { category -> count }

for (const item of $input.all()) {
  // "Glassdoor Jobs <noreply@glassdoor.com>" -> "noreply@glassdoor.com"
  const from = (item.json.From ?? '').match(/[\w.+-]+@[\w.-]+/)?.[0]?.toLowerCase();
  if (!from) continue;

  for (const l of item.json.labels ?? []) {
    // Ours all have Label_ ids. INBOX / UNREAD / CATEGORY_* don't. sorted is plumbing.
    if (!l.id.startsWith('Label_') || l.name === 'sorted') continue;

    // "jobs/alert" -> "job_alert", to match the classifier's category names
    const cat = l.name.startsWith('jobs/') ? 'job_' + l.name.slice(5) : l.name;

    counts[from] ??= {};
    counts[from][cat] = (counts[from][cat] ?? 0) + 1;
  }
}

const senderMap = {};

for (const [from, byCat] of Object.entries(counts)) {
  const [top, n] = Object.entries(byCat).sort((a, b) => b[1] - a[1])[0];
  const total = Object.values(byCat).reduce((s, x) => s + x, 0);

  // Needs real history and clear agreement before we trust it
  if (total >= 3 && n / total >= 0.8) senderMap[from] = { top, n, total };
}

return [{ json: { senderMap } }];

// Only these categories can need a reply
const REPLYABLE = ['general', 'job_application', 'job_interview'];

// Words that mean nobody reads that mailbox
const BULK_WORDS = [
  'noreply', 'no-reply', 'donotreply', 'do-not-reply', 'no_reply', 'dontreply',
  'automated', 'autoreply', 'auto-reply', 'daemon', 'mailer-daemon', 'robot',
  'notification', 'notifications', 'notify', 'alert', 'alerts',
  'newsletter', 'news', 'info', 'information', 'updates', 'status',
  'billing', 'invoice', 'receipts', 'orders', 'account', 'verify', 'verification',
  'feedback', 'survey',
];

return $input.all().filter(item => {
  if (!REPLYABLE.includes(item.json.category)) return false;

  if (item.json.isBulk) return false;

  // "Instahyre.com <noreply@instahyre.com>"  ->  "noreply"
  const from = (item.json.From ?? '').toLowerCase();
  /**
   * John Doe <john.doe@gmail.com>
   * ['john doe ', 'john.doe@gmail.com>']
   * 'john.doe@gmail.com>'
   * john.doe
   */
  const mailbox = (from.split('<').pop() ?? from).split('@')[0];

  /**
   * Checks if any word inside the mailbox name generated
   * .some() ->run for every word in the list, return true moment one matches, false if none
   * The ! flips it: a match means machine, which means DON'T keep
   */
  return !BULK_WORDS.some(word => mailbox.includes(word));
});

